#include "lumafem/analysis.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace lumafem;
ModelDefinition element(double L,int gp,const std::string& mapping){ModelDefinition d;d.identity={"energy-test","revision","snapshot","run",""};d.name="Uniform axial energy identity";d.geometry={L,10,10,0};MaterialParameters c;c.id="c";c.fc=30;c.e0=.002;c.fr=6;c.ft=3;c.Gft=.1;c.Gcp=10;c.unloadRatio=.1;c.referenceLength=100;c.crushReferenceStrain=.0035;d.materials={c};d.concreteMaterialId="c";d.reinforcement.mode="direct";d.discretization={"custom",L,gp,2,mapping};d.supports={{"left",0,{true,true,true},{0,0,0}},{"right",L,{false,true,true},{0,0,0}}};d.loads={{"axial",L,{100,0,0}}};d.controlX=L;d.controlComponent=0;d.controlDirection=1;d.observations.referencePhase="S0";return d;}
int main(){try{std::cout<<"mapping,length,gp,tension,compression,target_t,target_c\n";for(const std::string mapping:{"gauss_weight_v1","element_length_v2"})for(double L:{20.,50.,100.})for(int gp:{2,3,5}){auto prepared=prepareModel(element(L,gp,mapping));if(!prepared.ok)throw std::runtime_error("preparation failed");auto&m=prepared.model;if(m.elements.size()!=1)throw std::runtime_error("not one axial element");double tension=0,compression=0;for(auto&s:m.sections){auto p=s.fibers[0].material;double E=2*p.fc/p.e0;double endT=2*p.Gft/(p.lchT*p.ft);double du=2*p.Gcp/(p.fc+p.fr);double endC=p.e0+du/p.lchC-(p.fc-p.fr)/E;double opening=0,stressT=p.ft,delta=0,q=p.fc,et=0,ec=0;for(int i=1;i<=4000;++i){double e=p.ft/E+(endT-p.ft/E)*i/4000.;auto tr=evaluateMaterial(p,{},e);if(!tr.ok)throw std::runtime_error("tensile trial failed");double next=p.lchT*(e-tr.stress/E);et+=(stressT+tr.stress)*.5*(next-opening);opening=next;stressT=tr.stress;double cc=p.e0+(endC-p.e0)*i/4000.;auto cr=evaluateMaterial(p,{},-cc);if(!cr.ok)throw std::runtime_error("compressive trial failed");double nd=p.lchC*(cc-p.e0-(-cr.stress-p.fc)/E);ec+=(q-cr.stress)*.5*(nd-delta);delta=nd;q=-cr.stress;}tension+=100*s.integrationLength/p.lchT*et;compression+=100*s.integrationLength/p.lchC*ec;if(mapping=="element_length_v2"&&(s.lchT!=L||s.lchC!=L))throw std::runtime_error("constitutive length is not Le");}double multiplier=mapping=="element_length_v2"?1.:gp;double expectedT=100*.1*multiplier,expectedC=100*10.*multiplier;if(std::abs(tension-expectedT)>1e-6+.001*expectedT||std::abs(compression-expectedC)>1e-6+.001*expectedC)throw std::runtime_error("independent integrated energy identity failed");std::cout<<mapping<<','<<L<<','<<gp<<','<<tension<<','<<compression<<','<<expectedT<<','<<expectedC<<std::endl;}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
